// Included inside incremental_store::tests: real files/codec, no user save paths.
/// O(fixture), independent initial world with bounded temporal commands.
fn provenance_initial()->corpse_core::Run{let mut r=core().run;for a in r.actors.values_mut(){*a=std::sync::Arc::new(Vec::new());}r.player.hp=100_000.;r.player.max_hp=100_000.;r.player.base_max_hp=100_000.0.into();r.player.energy=100.;r.player.stats.max_energy=100.;r.player.abilities=vec!["numo-revert".into(),"morae-see-the-future".into()];r.player.active.clear();r.player.conditions.clear();r.offers.clear();for id in r.player.abilities.clone(){corpse_core::progression::initialize_ability_state(&mut r.player,&id,r.tick).unwrap();}r.player.conditions.insert("revertCharges".into(),20.);r.replay.clear();r.history.clear();r.replay_snapshot_from=corpse_core::Field::Missing;r}
/// O(command count), immutable policy metadata is part of the replay result.
fn replay_export_twice(initial:&corpse_core::Run,source:&CoreEngine){let record=corpse_core::replay::ReplayRecord::try_from_run(&source.run).unwrap();assert_eq!(record.version,2.);let encoded=serde_json::to_string(&record).unwrap();let record=serde_json::from_str(&encoded).unwrap();let mut playback=corpse_core::replay::ReplaySession::from_initial(initial.clone(),record).unwrap();for round in 0..2{if round>0{playback.restart().unwrap();}while playback.step().unwrap(){}assert_eq!(playback.engine.save().unwrap(),source.save().unwrap());}}
/// O(real checkpoint+append+replay), fresh snapshot policy survives reopen and both exports.
#[test]fn fresh_seed_policy_survives_recording_manual_export_and_restart(){let initial=provenance_initial();let mut e=tracked_engine::Engine::new(initial.clone()).unwrap();assert_eq!(e.run.replay_snapshot_from,corpse_core::Field::Value(0));let dir=Sandbox::new("seed-fresh");let path=dir.path();let mut auto=Autosave::default();auto.flush_tracked(&path,&e,Kind::Fixture,false).unwrap();for command in [Command::Wait,Command::Wait,Command::Ability{id:"numo-revert".into(),target:corpse_core::Field::Missing,x:corpse_core::Field::Missing,y:corpse_core::Field::Missing}]{e.dispatch(&command).unwrap();auto.flush_tracked(&path,&e,Kind::Fixture,false).unwrap();}let(restored,_)=decode_bytes(&std::fs::read(&path).unwrap()).unwrap();assert_eq!(restored.save().unwrap(),e.save().unwrap());replay_export_twice(&initial,&restored);let(manual,_)=super::super::decode_legacy(&restored.save().unwrap()).unwrap();assert_eq!(manual.run.replay_snapshot_from,corpse_core::Field::Value(0));replay_export_twice(&initial,&manual);}
/// O(old-tail replay+new commands), boundary uses retained ledger index after Revert.
#[test]fn mixed_old_tail_then_snapshot_seed_export_is_exact(){let initial=provenance_initial();let mut old=CoreEngine::new(initial.clone()).unwrap();old.set_legacy_revert(true);let checkpoint=encode(&old,Kind::Fixture).unwrap();let header=log::Header{replay_build:log::LEGACY_REPLAY_BUILD_ID.into(),simulation_revision:log::SIMULATION_REVISION};let mut file=log::encode_initial(&checkpoint,&header).unwrap();for command in [Command::Wait,Command::Pickup,Command::Wait,Command::Ability{id:"numo-revert".into(),target:corpse_core::Field::Missing,x:corpse_core::Field::Missing,y:corpse_core::Field::Missing}]{old.dispatch(&command).unwrap();let payload=serde_json::to_string(&Batch{receipts:vec![Receipt{command,after:tracked_engine::Stamp::capture(&old)}]}).unwrap();let next=log::encode_append(file.next_sequence,file.last_checksum,&payload).unwrap();file.bytes.extend_from_slice(&next.bytes);file.next_sequence=next.next_sequence;file.last_checksum=next.last_checksum;}
 let(mut migrated,_)=decode_bytes(&file.bytes).unwrap();let boundary=old.run.replay.len();assert_eq!(migrated.run.replay_snapshot_from,corpse_core::Field::Value(boundary));assert_ne!(boundary as f64,migrated.run.tick);for command in [Command::Wait,Command::Ability{id:"numo-revert".into(),target:corpse_core::Field::Missing,x:corpse_core::Field::Missing,y:corpse_core::Field::Missing}]{migrated.dispatch(&command).unwrap();}replay_export_twice(&initial,&migrated);let checkpoint=encode(&migrated,Kind::Fixture).unwrap();let(reopened,_)=super::super::decode_legacy(&checkpoint).unwrap();assert_eq!(reopened.run.replay_snapshot_from,corpse_core::Field::Value(boundary));replay_export_twice(&initial,&reopened);
}
/// O(checkpoint bytes), known old experimental header cannot invent seed ancestry.
#[test]fn unknown_experimental_seed_export_fails_but_session_roundtrips(){let mut e=CoreEngine::new(provenance_initial()).unwrap();e.dispatch(&Command::Wait).unwrap();let mut checkpoint:serde_json::Value=serde_json::from_str(&encode(&e,Kind::Fixture).unwrap()).unwrap();checkpoint["run"].as_object_mut().unwrap().remove("replaySnapshotFrom");let checkpoint=serde_json::to_string(&checkpoint).unwrap();let bytes=log::encode_initial(&checkpoint,&log::Header::current()).unwrap().bytes;let(unknown,_)=decode_bytes(&bytes).unwrap();assert!(matches!(unknown.run.replay_snapshot_from,corpse_core::Field::Null));assert!(corpse_core::replay::ReplayRecord::try_from_run(&unknown.run).unwrap_err().to_string().contains("unknown"));let(reopened,_)=super::super::decode_legacy(&unknown.save().unwrap()).unwrap();assert!(matches!(reopened.run.replay_snapshot_from,corpse_core::Field::Null));assert!(corpse_core::replay::ReplayRecord::try_from_run(&reopened.run).is_err());let(legacy_convention,_)=super::super::decode_legacy(&checkpoint).unwrap();assert_eq!(legacy_convention.run.replay_snapshot_from,corpse_core::Field::Value(e.run.replay.len()));}
/// O(initial/reopen checkpoint), unavailable seed export must not newly delete terminal data.
#[test]fn unknown_terminal_policy_preserves_checkpoint_and_archive_files(){let mut run=provenance_initial();run.replay_snapshot_from=corpse_core::Field::Null;run.status="dead".into();run.player.hp=0.;run.run_id="unknown-policy-terminal".to_string().into();let engine=tracked_engine::Engine::new(run).unwrap();let dir=Sandbox::new("unknown-terminal");let path=dir.path();let mut auto=Autosave::default();auto.flush_tracked(&path,&engine,Kind::Genuine,false).unwrap();let before=std::fs::read(&path).unwrap();auto.flush_tracked(&path,&engine,Kind::Genuine,false).unwrap();assert_eq!(std::fs::read(&path).unwrap(),before);assert_disk(&path,&engine,Kind::Genuine);let profile=corpse_core::profile::Profile::default();assert!(super::super::prepare(&profile,&engine.run,Kind::Genuine,true,None).err().unwrap().contains("unknown"));let profile_path=dir.0.join("profile.json");let replay_path=dir.0.join("replay.json");std::fs::write(&profile_path,b"protected profile").unwrap();std::fs::write(&replay_path,b"protected replay").unwrap();assert!(corpse_core::replay::ReplayRecord::try_from_run(&engine.run).is_err());assert_eq!(std::fs::read(profile_path).unwrap(),b"protected profile");assert_eq!(std::fs::read(replay_path).unwrap(),b"protected replay");}

/// O(authored Future trace + checkpoint loads), export/restart retains policy through anchors.
#[test]fn future_policy_export_after_each_checkpoint_resume(){let cases:serde_json::Value=serde_json::from_str(include_str!("../../../fixtures/temporal-command-traces-v48.json")).unwrap();let case=cases.as_array().unwrap().iter().find(|c|c["name"]=="future retained costs and resume").unwrap();let mut initial:corpse_core::Run=serde_json::from_value(case["initial"].clone()).unwrap();initial.simulation_revision=39.0.into();initial.replay_snapshot_from=corpse_core::Field::Missing;let mut engine=CoreEngine::new(initial.clone()).unwrap();for step in case["steps"].as_array().unwrap(){let command:Command=serde_json::from_value(step["command"].clone()).unwrap();engine.dispatch(&command).unwrap();let encoded=encode(&engine,Kind::Fixture).unwrap();engine=super::super::decode_legacy(&encoded).unwrap().0;assert_eq!(engine.run.replay_snapshot_from,corpse_core::Field::Value(0));replay_export_twice(&initial,&engine);}}
